      out.push('   <GROUP NAME="' + x(g.name) + '" ACTION="Create">\n    <NAME>' + x(g.name) + '</NAME>\n    <PARENT>' + x(up && !up.builtin ? up.name : tallyTop(NS.partyGroup({ group: g.id }, M.groups).top)) + '</PARENT>\n   </GROUP>\n');
